library(creditratingsystem)
if(!exists('.cr_hash',mode='function')) .cr_hash<-getFromNamespace('.cr_hash','creditratingsystem')
re_rows<-Map(function(f,v)list(feature_id=f,contribution=v),c('a','a_squared','b','c','other'),c(3,-1,2,-4,1));re_basis<-list(attribution_id='a',model_id='m',model_version='1',reference_id='r',explained_quantity='default_log_odds',output_scale='log_odds',baseline=-2,prediction=-1,adverse_direction='HIGHER')
re_dict<-list(dictionary_id='d',version='1',model_reasons=list(list(reason_code='A',description='A grouped contribution',priority=2,feature_ids=list('a','a_squared')),list(reason_code='B',description='B contribution',priority=1,feature_ids=list('b')),list(reason_code='C',description='C contribution',priority=0,feature_ids=list('c'))),policy_reasons=list())
re_r<-rank_credit_reason_codes(re_rows,re_basis,re_dict,max_reasons=1)$value;stopifnot(re_r$model_reasons[[1]]$reason_code=='B',re_r$omitted_by_limit[[1]]$reason_code=='A',re_r$omitted_by_limit[[1]]$contribution==2,re_r$suppressed_groups[[1]]$reason_code=='C',abs(re_r$coverage$mapped_absolute_fraction-10/11)<1e-14,re_r$reconstruction_residual==0)
re_basis$adverse_direction<-'LOWER';stopifnot(rank_credit_reason_codes(re_rows,re_basis,re_dict)$value$model_reasons[[1]]$reason_code=='C');re_basis$adverse_direction<-'HIGHER'
re_error<-function(expr,code){e<-tryCatch(force(expr),error=identity);stopifnot(inherits(e,'creditratingsystem_error'),identical(e$code,code))}
re_bad<-re_basis;re_bad$prediction<-0;re_error(rank_credit_reason_codes(re_rows,re_bad,re_dict),'REASON_RECONSTRUCTION');re_bad<-re_dict;re_bad$model_reasons[[2]]$feature_ids<-list('a');re_error(rank_credit_reason_codes(re_rows,re_basis,re_bad),'REASON_GROUPS')
re_trace<-list(rule_id='eligibility',reason_code='NOT_ELIGIBLE',matched=TRUE,selected=TRUE,action='DECLINE',sources=list('eligibility'));re_d<-list(schema_version='1.0',kind='DecisionArtifact',action='DECLINE',findings=list('eligibility.check'),rule_trace=list(re_trace));re_d$sha256<-.cr_hash(re_d);re_dict$policy_reasons<-list(list(reason_code='NOT_ELIGIBLE',description='Eligibility condition failed',priority=0,rule_ids=list('eligibility')))
re_r<-rank_credit_reason_codes(re_rows,re_basis,re_dict,policy_decision=re_d)$value;stopifnot(length(re_r$model_reasons)==2,length(re_r$policy_reasons)==1,identical(re_r$policy_reasons[[1]]$rules,list(re_trace)),re_r$policy_decision_hash==re_d$sha256)
